package com.jnapanam.sportszone.admin.controller;
import com.jnapanam.sportszone.admin.dto.OperationalReasonRequest;import com.jnapanam.sportszone.booking.dto.BookingResponse;import com.jnapanam.sportszone.booking.service.BookingService;import com.jnapanam.sportszone.payment.dto.*;import com.jnapanam.sportszone.payment.service.PaymentService;import jakarta.validation.Valid;import java.util.UUID;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;
@RestController@RequestMapping("/api/v1/operations")@PreAuthorize("hasAnyRole('SUPER_ADMIN','ADMIN','OPERATIONS')")public class OperationsController{
 private final BookingService bookings;private final PaymentService payments;public OperationsController(BookingService bookings,PaymentService payments){this.bookings=bookings;this.payments=payments;}
 @PostMapping("/bookings/{bookingNumber}/check-in")public BookingResponse checkIn(Authentication auth,@PathVariable String bookingNumber,@Valid@RequestBody(required=false)BookingCheckInRequest request){return bookings.checkIn(UUID.fromString(auth.getName()),bookingNumber,request);}
 @PostMapping("/bookings/{id}/check-out")public BookingResponse checkOut(Authentication auth,@PathVariable UUID id){return bookings.checkOut(UUID.fromString(auth.getName()),id);}
 @PostMapping("/bookings/{id}/check-in/reverse")public BookingResponse reverse(@PathVariable UUID id){return bookings.undoCheckIn(id);}
 @PostMapping("/bookings/{id}/cancel")public BookingResponse cancel(@PathVariable UUID id,@Valid@RequestBody(required=false)OperationalReasonRequest request){return bookings.adminCancel(id,request==null?null:request.reason());}
 @PostMapping("/bookings/{id}/no-show")public BookingResponse noShow(@PathVariable UUID id,@Valid@RequestBody(required=false)OperationalReasonRequest request){return bookings.noShow(id,request==null?null:request.reason());}
 @PostMapping("/bookings/{id}/cancel-and-refund")public BookingCancellationRefundResponse cancelAndRefund(@PathVariable UUID id,@Valid@RequestBody(required=false)OperationalReasonRequest request){return payments.cancelBookingAndRefund(id,request==null?null:request.reason());}
 @PostMapping("/bookings/{id}/collect-payment")public PaymentResponse collectPayment(Authentication auth,@PathVariable UUID id,@Valid@RequestBody OnsitePaymentRequest request){return payments.collectOnsite(UUID.fromString(auth.getName()),id,request);}
}
